InvokeScript:
$Path = Resolve-Path -Path "$Env:ProgramFiles (x86)\Microsoft\Edge\Application\*\Installer\setup.exe" | Select-Object -Last 1

if (Test-Path $Path) {
    New-Item -Path "$Env:SystemRoot\SystemApps\Microsoft.MicrosoftEdge_8wekyb3d8bbwe\MicrosoftEdge.exe" -Force
    Start-Process -FilePath $Path -ArgumentList "--uninstall --system-level --force-uninstall --delete-profile" -Wait
    Write-Host "Microsoft Edge was removed"
} else {
    Write-Host "Microsoft Edge is not installed"
}

$adapters = @(Get-WinUtilDisplayAdapterKey -Vendor NVIDIA)
if ($adapters.Count -eq 0) {
  Write-Host 'No NVIDIA graphics card found, nothing to change.'
  return
}
Set-WinUtilRegistryWithBackup -Name 'AdvNvidiaHdcp' -Path $adapters -Settings @(@{ Name = 'RMHdcpKeyglobZero'; Type = 'DWord'; Value = 1 })

Set-WinUtilPowerSettingWithBackup -Name 'AdvSleepStates' -Settings @(
  @{ SubGroup = 'SUB_SLEEP'; Setting = 'AWAYMODE'; AC = 0 },
  @{ SubGroup = 'SUB_SLEEP'; Setting = 'ALLOWSTANDBY'; AC = 0 },
  @{ SubGroup = 'SUB_SLEEP'; Setting = 'HYBRIDSLEEP'; AC = 0 }
)

if ((Get-CimInstance Win32_Processor | Select-Object -First 1).Manufacturer -ne 'GenuineIntel') {
  Write-Host 'This PC does not have an Intel processor, skipping the boot settings.'
  return
}
bcdedit.exe /set allowedinmemorysettings 0x0
bcdedit.exe /set isolatedcontext No
